const L = {
  other: (text: string, label: string | null = null) => ({ kind: 'other', text, label }),
  special: (text: string, label: string) => ({ kind: 'special', text, label }),
  plan: (text: string, f: string, total: string | null = null) => ({ kind: 'plan', text, for: f, total }),
};
const O = (name: string, price: string | null, doc: string, lines?: unknown[]) => ({ name, description: 'A description.', price, url: null, sourceDocumentId: doc, ...(lines ? { pricing: { lines } } : {}) });
/** An honest structured answer (site prompt 1.8.0): every offer named as its own priced card names it and cited to the
 * page carrying that card (the Join page; the cheat sheets' "Free" row is on the Home page). `id` maps a path to its document id. */
export function mhpRealJoinAnswer(id: Record<string, string>): Record<string, unknown> {
  const J = id['/join/']!, HM = id['/']!;
  return { summary: 'Martin Howard Property teaches property investing in Wales and England, one lane at a time.', audiences: [], positioning: '', conversionPages: [],
    voice: { tone: [], do: [], dont: [], examples: [] }, approvedClaims: [], exclusions: [], conflicts: [], missingFacts: [], sources: [],
    offers: [O('Free cheat sheets', 'Free', HM, []), O('The Deal Desk', '£47', J),
      O('Property Done Properly', '£1,497', J, [L.plan('3 x £525', '£1,497'), L.special('£997', 'Webinar price'), L.plan('3 x £349', '£997')]),
      O("The Members' Room", '£67 a month', J, [L.other('£670 a year'), L.special('£47 a month', "Founders' price")]),
      O('One Lane Mentoring', '£3,997', J, [L.plan('6 x £699', '£3,997', '£4,194 in total')]), O('One Lane Private', '£25,000', J, [L.plan('12 x £2,250', '£25,000', '£27,000 in total')]),
      O('The Deal Partnership', '£7,500', J)] };
}
/** The same honest answer cited to the Home table, named as the table writes each row (the reviewer's V2). */
export function mhpRealHomeAnswer(id: Record<string, string>): Record<string, unknown> {
  const J = id['/join/']!, HM = id['/']!;
  return { ...mhpRealJoinAnswer(id), offers: [O('Free cheat sheets', 'Free', HM, []), O('The Deal Desk', '£47', HM),
    O('Property Done Properly', '£1,497', HM, [L.special('£997', 'for seven days after a webinar'), L.plan('3 x £525', '£1,497'), L.plan('3 x £349', '£997')]),
    O("Members' Room", '£67 a month', HM, [L.special('£47', 'for the first 100')]), O('One Lane Mentoring', '£3,997', HM, [L.plan('6 x £699', '£3,997', '£4,194 in total')]),
    O('One Lane Private', '£25,000', J, [L.plan('12 x £2,250', '£25,000', '£27,000 in total')]), O('Deal Partnership', '£7,500', HM)] };
}
